<?php
if(PHP_SAPI!=='cli'||getenv('PHPBB_ARCADE_TOUR_JOIN_NATIVE')!=='1'){echo "Tournament join checks require an explicitly enabled disposable database.\n";return;}
require __DIR__.'/arcade-tournament-join-fixture.php';
class TournamentJoinNativeDatabase extends ArcadeSubmissionNativeDatabase
{
    function __construct($host,$user,$password,$schema,$persistent=false,$owned=false){parent::__construct($host,$user,$password,$schema,false,$owned);$this->fixture_factory=function()use($host,$user,$password,$schema){return new TournamentJoinNativeDatabase($host,$user,$password,$schema,false,true);};}
    function sql_query($sql='',$transaction=false){
        global $ag_peer,$ag_async,$su_observer;
        $r=parent::sql_query($sql,$transaction);
        if($this->owned&&!$this->fired&&strpos($this->fault,'join-peer-')===0&&strpos($sql,'INSERT INTO fixture_ina_tour_play ')===0){
            as_check($r!==false,'Actual uncommitted enrolment');$this->fired=true;
            $changes=array('join-peer-session'=>"DELETE FROM fixture_sessions WHERE session_id='fixture-import'",'join-peer-active'=>'UPDATE fixture_users SET user_active=0 WHERE user_id=2',
                'join-peer-group'=>'DELETE FROM fixture_user_group WHERE user_id=2 AND group_id=5','join-peer-config'=>"UPDATE fixture_ina_data SET config_value='1' WHERE config_name='games_offline'",'join-peer-tour'=>'UPDATE fixture_ina_tour SET tour_active=3 WHERE tour_id=9');
            as_check(isset($changes[$this->fault])&&mysqli_query($ag_peer->db_connect_id,$changes[$this->fault],MYSQLI_ASYNC),'Queue actual competing access/state change');$ag_async=true;
            native_fixture_wait_for_lock($su_observer,mysqli_thread_id($ag_peer->db_connect_id),mysqli_thread_id($this->db_connect_id),'as_check');
        }
        return $r;
    }
}
function tj_reset($config=array()){
    su_reset($config);ag_sql('START TRANSACTION');ag_sql('DELETE FROM fixture_ina_tour_play');
    ag_sql("INSERT INTO fixture_ina_tour(tour_id,tour_name,tour_active,tour_max_players) VALUES(9,'Grüße 😀 &amp; <tour>',2,2),(10,'Second',2,2),(11,'Finished',3,2)");
    ag_sql('INSERT INTO fixture_ina_tour_play(tour_id,user_id) VALUES(9,8)');ag_sql('COMMIT');
    profile_fixture_request(array('sid'=>'fixture-import','join'=>'1'));$_SERVER['REQUEST_METHOD']='POST';$_SERVER['HTTP_SEC_FETCH_SITE']='same-origin';
}
function tj_snapshot(){return array(su_rows('SELECT * FROM fixture_ina_tour_play ORDER BY tour_id,user_id'),su_rows('SELECT * FROM fixture_ina_log ORDER BY user_id,name,value,date'));}
$db=$control=$ag_peer=$su_observer=null;$created=false;$schema='codex_tour_join_'.bin2hex(phpbb_random_bytes(8));$cases=$serialized=0;
try{
    $port=getenv('PHPBB_ARCADE_GAME_PORT')?:'3306';as_check(preg_match('/^[0-9]{1,5}$/D',$port)&&(int)$port>0&&(int)$port<=65535,'Own loopback port');$host='127.0.0.1:'.$port;$password=getenv('PHPBB_ARCADE_GAME_PASSWORD')?:'';
    $control=new sql_db($host,'root',$password,'',false);as_check($control->sql_query('CREATE DATABASE '.$schema.' CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci'),'Own join schema');$created=true;
    $db=new TournamentJoinNativeDatabase($host,'root',$password,$schema,false);$ag_peer=new sql_db($host,'root',$password,$schema,false);$su_observer=new sql_db($host,'root',$password,$schema,false);su_schema();as_open();$ag_routes=aif_routes();
    foreach(array('english','german')as$locale){tj_reset();as_language($locale);$body=tj_controller();as_check(strpos($body,sprintf($lang['tour_joined'],htmlspecialchars('Grüße 😀 &amp; <tour>',ENT_QUOTES,'UTF-8')))!==false,'Actual localized controller reports committed enrolment with exact escaped caption');as_check(count(su_rows('SELECT * FROM fixture_ina_tour_play WHERE tour_id=9'))===2,'One final seat added');as_check(tj_status(tj_call(),'tour_member'),'Repeated join of a now-full tournament reports existing membership');$cases++;}
    tj_reset();ag_sql('UPDATE fixture_ina_tour SET tour_max_players=1 WHERE tour_id=9');$before=tj_snapshot();as_check(tj_status(tj_call(),'tour_full')&&tj_snapshot()===$before,'Full event never adds member or audit');$cases++;
    tj_reset();as_check(tj_status(tj_call(),'tour_joined'),'First actual writer reserves the last seat');ag_sql("INSERT INTO fixture_users(user_id,username,user_password,user_active) VALUES(9,'Next','',1)");ag_sql("INSERT INTO fixture_sessions(session_id,session_user_id,session_logged_in) VALUES('next-member',9,1)");$userdata['user_id']=9;$userdata['session_id']='next-member';profile_fixture_request(array('sid'=>'next-member'));$before=tj_snapshot();as_check(tj_status(tj_call(),'tour_full')&&tj_snapshot()===$before,'A second actual member cannot overbook the final seat');$cases++;
    foreach(array('wrong','nested')as$bad){tj_reset();$before=tj_snapshot();$body=tj_controller(array('9'),array('sid'=>$bad==='wrong'?'wrong':array()));as_check($body===$lang['Not_Authorised']&&tj_snapshot()===$before,'Actual controller refuses invalid CSRF before any mutation '.$bad);$cases++;}
    tj_reset();$r=tj_call(array('10','9','10','11','12'));as_check(!$r['error']&&array_column($r['results'],'status')===array('tour_joined','tour_joined'),'Batch preserves selection order, deduplicates and ignores nonactive/missing events');as_check(count(su_rows('SELECT * FROM fixture_ina_tour_play WHERE user_id=2'))===2,'Exactly one membership per selected active tournament');$cases++;
    foreach(array('session','logged-out','owner','case-session','inactive','removed','ban','offline','posts','rank','group','pending-group','category-group')as$bad){
        tj_reset();if($bad==='session'){ag_sql("DELETE FROM fixture_sessions WHERE session_id='fixture-import'");}elseif($bad==='logged-out'){ag_sql('UPDATE fixture_sessions SET session_logged_in=0');}elseif($bad==='owner'){ag_sql('UPDATE fixture_sessions SET session_user_id=8');}elseif($bad==='case-session'){$userdata['session_id']='FIXTURE-IMPORT';$HTTP_POST_VARS['sid']='FIXTURE-IMPORT';}elseif($bad==='inactive'){ag_sql('UPDATE fixture_users SET user_active=0 WHERE user_id=2');}elseif($bad==='removed'){ag_sql('DELETE FROM fixture_users WHERE user_id=2');}elseif($bad==='ban'){ag_sql('UPDATE fixture_users SET arcade_banned=1 WHERE user_id=2');}elseif($bad==='offline'){ag_sql("UPDATE fixture_ina_data SET config_value='1' WHERE config_name='games_offline'");}elseif($bad==='posts'||$bad==='rank'){ag_sql("UPDATE fixture_ina_data SET config_value='1' WHERE config_name='games_".$bad."_required'");}elseif($bad==='category-group'){ag_sql('UPDATE fixture_ina_cat SET group_required=5 WHERE cat_id=-1');}else{ag_sql("UPDATE fixture_ina_data SET config_value='5' WHERE config_name='games_group_required'");if($bad==='pending-group'){ag_sql("INSERT INTO fixture_groups(group_id,group_name,group_description,group_single_user) VALUES(5,'Fixture','',0)");ag_sql('INSERT INTO fixture_user_group(user_id,group_id,user_pending) VALUES(2,5,1)');}}
        $before=tj_snapshot();as_check(tj_call()['error']&&tj_snapshot()===$before,'Fresh authority refuses enrolment without changes '.$bad);$cases++;
    }
    foreach(array('write-1','write-2','write-3','write-4','audit','commit','commit-after')as$fault){tj_reset();$before=tj_snapshot();$db->fault=$fault;$r=tj_call(array('9','10'));as_check($r['error'],'No successful response after join/audit/commit failure '.$fault);if($fault!=='commit-after'){as_check(tj_snapshot()===$before,'Whole batch and audit roll back '.$fault);}else{as_check(count(su_rows('SELECT * FROM fixture_ina_tour_play WHERE user_id=2'))===2,'Unknown commit acknowledgement is never replayed');}$cases++;}
    foreach(array('session','active','group','config','tour')as$kind){tj_reset();if($kind==='group'){ag_sql("UPDATE fixture_ina_data SET config_value='5' WHERE config_name='games_group_required'");ag_sql("INSERT INTO fixture_groups(group_id,group_name,group_description,group_single_user) VALUES(5,'Fixture','',0)");ag_sql('INSERT INTO fixture_user_group(user_id,group_id,user_pending) VALUES(2,5,0)');}$db->fault='join-peer-'.$kind;as_check(tj_status(tj_call(),'tour_joined'),'Enrolment commits before observed competing change '.$kind);ag_reap();$before=tj_snapshot();$r=tj_call();as_check(($kind==='tour'?!$r['error']&&$r['results']===array():$r['error'])&&tj_snapshot()===$before,'Following enrolment observes completed change '.$kind);$cases++;$serialized++;}
    foreach(array('success','same','missing')as$factory){tj_reset();as_check($db->sql_query('START TRANSACTION')&&$db->sql_query("UPDATE fixture_groups SET group_name='Caller' WHERE group_id=99"),'Own caller transaction canary');if($factory!=='success'){$db->factory_mode=$factory;}$r=tj_call();as_check(tj_status($r,'tour_joined')===($factory==='success')&&su_rows('SELECT group_name FROM fixture_groups WHERE group_id=99')[0]['group_name']==='Sentinel'&&$db->sql_query('ROLLBACK'),'Caller transaction never borrowed or committed '.$factory);$cases++;}
    foreach(array(iNA_TOUR,iNA_TOUR_PLAY,USERS_TABLE,iNA_LOG)as$table){tj_reset();ag_sql('ALTER TABLE '.$table.' ENGINE=MyISAM');$before=tj_snapshot();as_check(tj_call()['error']&&tj_snapshot()===$before,'Legacy engine refused '.$table);ag_sql('ALTER TABLE '.$table.' ENGINE=InnoDB ROW_FORMAT=DYNAMIC');$cases++;}
    tj_reset(array('games_use_log'=>0));as_check(tj_status(tj_call(),'tour_joined')&&su_rows('SELECT * FROM fixture_ina_log')===array(),'Disabled audit respected');$cases++;
    tj_reset();$db->factory_mode='no-backslash';as_check(tj_status(tj_call(),'tour_joined'),'Alternate SQL mode retains literal event metadata');$cases++;
    echo 'Native Arcade tournament joins: '.$cases.' cases, '.$serialized.' serialized changes, '.$as_checks." assertions PASS; actual controller, exact capacity, current access, batch/audit rollback and owned transactions.\n";
}finally{ag_reap();su_close();if($db){$db->sql_close();}if($ag_peer){$ag_peer->sql_close();}if($su_observer){$su_observer->sql_close();}if($created){as_check(preg_match('/^codex_tour_join_[a-f0-9]{16}$/D',$schema)&&$control->sql_query('DROP DATABASE '.$schema),'Drop exact own join schema');}if($control){$control->sql_close();}}
